/// Sample a single `(col, row)` character cell from a `1920x1080` (or arbitrary resolution)
/// RGB frame into 120 4-bit normalized intensity nibbles (`0..=15`).
/// Returns `None` if the cell is dark/empty space.
pub fn sample_cell_nibbles_120(rgb: &RgbImage, col: usize, row: usize) -> Option<[u8; 120]> {
    let w = rgb.width() as usize;
    let h = rgb.height() as usize;
    if w < 640 || h < 475 || col >= CONSOLE_COLS || row >= CONSOLE_ROWS {
        return None;
    }

    let mut raw_v = [0u8; 120];
    let mut max_v: u32 = 1;
    let mut active_px: usize = 0;
    let mut idx = 0usize;

    let mut gy = 2usize;
    while gy < 17 {
        let sy_1080 = 112 + ((row * 19 + gy) * 9 + 4) / 5;
        let sy = ((sy_1080 * h) / 1080).min(h.saturating_sub(1));
        let mut gx = 0usize;
        while gx < 8 {
            let sx_1920 = 192 + ((col * 8 + gx) * 12 + 6) / 5;
            let sx = ((sx_1920 * w) / 1920).min(w.saturating_sub(1));
            let p = rgb.get_pixel(sx as u32, sy as u32);
            let v = p[0].max(p[1]).max(p[2]);
            raw_v[idx] = v;
            if (v as u32) > max_v {
                max_v = v as u32;
            }
            if v > 65 {
                active_px += 1;
            }
            idx += 1;
            gx += 1;
        }
        gy += 1;
    }

    if max_v < 80 || active_px < 4 {
        return None;
    }

    let mut out = [0u8; 120];
    let mut i = 0usize;
    while i < 120 {
        out[i] = (((raw_v[i] as u32) * 15) / max_v) as u8;
        i += 1;
    }
    Some(out)
}

/// Match 120 4-bit cell nibbles against `GLYPH_TEMPLATES` using pure-integer squared L2 distance.
pub fn match_glyph_ascii(cell: &[u8; 120], col: usize) -> char {
    let phase = (col % 5) as u8;
    let mut best_ascii: u8 = b'?';
    let mut best_dist: u32 = u32::MAX;

    let mut t_idx = 0usize;
    while t_idx < GLYPH_TEMPLATES.len() {
        let tpl = &GLYPH_TEMPLATES[t_idx];
        let mut dist: u32 = if tpl.phase == phase { 0 } else { 250 };
        let mut k = 0usize;
        while k < 60 {
            let packed = tpl.packed_nibbles[k];
            let t0 = (packed >> 4) as i32;
            let t1 = (packed & 0x0F) as i32;
            let d0 = (cell[k * 2] as i32) - t0;
            let d1 = (cell[k * 2 + 1] as i32) - t1;
            dist += (d0 * d0 + d1 * d1) as u32;
            if dist >= best_dist {
                break;
            }
            k += 1;
        }
        if dist < best_dist {
            best_dist = dist;
            best_ascii = tpl.ascii;
        }
        t_idx += 1;
    }
    best_ascii as char
}

/// Transcribe all 25 rows x 80 columns of a UEFI / BIOS / AyeOS HDMI RGB frame into trimmed ASCII lines.
pub fn transcribe_rgb_console_80x25(rgb: &RgbImage) -> Vec<String> {
    let mut lines = Vec::new();
    let mut row = 0usize;
    while row < CONSOLE_ROWS {
        let mut line = String::with_capacity(CONSOLE_COLS);
        let mut col = 0usize;
        while col < CONSOLE_COLS {
            if let Some(nibbles) = sample_cell_nibbles_120(rgb, col, row) {
                line.push(match_glyph_ascii(&nibbles, col));
            } else {
                line.push(' ');
            }
            col += 1;
        }
        let trimmed = line.trim_end().to_string();
        if !trimmed.is_empty() {
            lines.push(trimmed);
        }
        row += 1;
    }
    lines
}

/// Rolling C64-disciplined LLM Screen Transcription & Context Buffer.
#[derive(Clone, Debug, Default)]
pub struct LlmScreenTranscriptBuffer {
    pub last_lines: Vec<String>,
    pub rolling_log: Vec<String>,
}

impl LlmScreenTranscriptBuffer {
    pub const fn new() -> Self {
        Self {
            last_lines: Vec::new(),
            rolling_log: Vec::new(),
        }
    }

    /// Update the rolling LLM context buffer with newly transcribed screen lines.
    /// Only appends lines that changed or appeared since the previous frame.
    pub fn ingest_transcribed_lines(&mut self, frame_seq: u64, lines: &[String]) -> Vec<String> {
        for line in lines {
            let trimmed = line.trim();
            if trimmed.len() < 2 {
                continue;
            }
            // Skip pure border separator lines in the rolling event log
            if trimmed.chars().all(|c| c == '=' || c == '-') {
                continue;
            }
            if !self.last_lines.contains(line) {
                let entry = format!("[frame #{frame_seq}] {trimmed}");
                if self.rolling_log.last() != Some(&entry) {
                    self.rolling_log.push(entry);
                    if self.rolling_log.len() > LLM_BUFFER_CAPACITY {
                        self.rolling_log.remove(0);
                    }
                }
            }
        }
        self.last_lines = lines.to_vec();
        self.rolling_log.clone()
    }
}
